// weights-verify — the compatibility-verification harness.
//
// Usage: weights-verify <reference.nwf> <candidate.nwf>
//
// The reference file carries the plan's REQUEST MANIFEST (generated by
// `demo-native --dump-weights` from the plan itself; its content is
// irrelevant). The candidate is any weight file: the harness verifies the
// candidate's container structure and content, then its compatibility
// with the request manifest (identity and shape of every tensor). Every
// problem is printed with its tensor named. Exit 0 = accepted; exit 1 =
// rejected or a read error; exit 2 = usage.
//
// Data-free: it verifies metadata and content finiteness only. It loads
// no reference values and performs no quality or equivalence claims -
// reference validation against real weights is the separate single step
// `vr/validate-weights.sh <file>`.

#include <cstdio>
#include <cstring>

#include "native-weights-file.hpp"

int main(int argc, char** argv) {
    using namespace dlss5_nr::weightsfile;
    if (argc != 3) {
        std::fprintf(stderr,
                     "usage: weights-verify <reference.nwf> <candidate.nwf>\n"
                     "  reference: demo-native --dump-weights output (the "
                     "plan's request manifest)\n"
                     "  candidate: the weight file to accept or reject\n");
        return 2;
    }
    WeightsFile reference;
    WeightsFileError rerr;
    if (!load_file(argv[1], reference, rerr)) {
        std::fprintf(stderr, "reference file rejected:\n%s\n",
                     rerr.str().c_str());
        return 1;
    }
    WeightsFile candidate;
    WeightsFileError cerr;
    if (!load_file(argv[2], candidate, cerr)) {
        std::fprintf(stderr, "candidate file rejected:\n%s\n",
                     cerr.str().c_str());
        return 1;
    }
    WeightsFileError verr;
    if (!verify_compatibility(candidate, reference.records, verr)) {
        std::fprintf(stderr, "candidate is NOT compatible with the plan:\n%s\n",
                     verr.str().c_str());
        return 1;
    }
    std::printf("weights-verify: ACCEPTED\n");
    std::printf("  candidate: %s (%zu tensors, %zu payload bytes)\n", argv[2],
                candidate.records.size(), candidate.payload.size());
    std::printf("  manifest:  %s (%zu requested tensors)\n", argv[1],
                reference.records.size());
    return 0;
}
